<script setup lang="ts">
import { computed, ref } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { ElMessageBox } from 'element-plus'
import { api, type Model } from '../api/client'
import { useSession } from '../stores/session'
import { useAction } from '../composables/useAction'
import DetailDrawer from './DetailDrawer.vue'
import StatusTag from './StatusTag.vue'
const props=defineProps<{id:string}>();const emit=defineEmits<{close:[]}>()
const session=useSession(), {busy,run}=useAction(), evidence=ref(false), voucher=ref<Model<'Voucher'>|null>(null)
const detail=useQuery({queryKey:computed(()=>['invoice',session.tenant,props.id]),queryFn:()=>api('/invoices/{id}','get',{tenant:session.tenant,id:props.id}),enabled:computed(()=>!!props.id)})
const row=computed(()=>detail.data.value)
async function verify(){await run(`verify:${props.id}`,key=>api('/invoices/{id}/verify','post',{tenant:session.tenant,id:props.id,key}),'模拟查验已完成')}
async function suggest(){await run(`suggest:${props.id}`,key=>api('/invoices/{id}/suggestions','post',{tenant:session.tenant,id:props.id,key}),'入账建议已生成')}
async function accept(){const suggestion=row.value?.suggestion;if(!suggestion)return;try{await ElMessageBox.confirm(suggestion.need_review?'该建议需人工复核。请核对业务用途、科目和票面信息，确认后生成演示凭证。':'确认采纳当前建议并生成演示凭证？','确认入账',{confirmButtonText:'确认采纳',cancelButtonText:'返回核对',type:suggestion.need_review?'warning':'info'})}catch{return}await run(`accept:${suggestion.id}`,key=>api('/suggestions/{id}/accept','post',{tenant:session.tenant,id:suggestion.id,key}),'已入账，可查看凭证')}
async function showVoucher(){if(!row.value?.voucher_id)return;await run(`voucher:${row.value.voucher_id}`,async()=>{voucher.value=await api('/vouchers/{id}','get',{tenant:session.tenant,id:row.value?.voucher_id})},'凭证已加载')}
</script>
<template><DetailDrawer :model-value="!!id" title="发票详情" @update:model-value="!$event&&emit('close')"><div v-loading="detail.isPending.value"><div v-if="detail.error.value" role="alert" class="error-state"><p>{{detail.error.value.message}}</p><el-button @click="detail.refetch()">重试</el-button></div><template v-if="row"><div class="detail-heading"><div><small>{{row.kind}} · {{row.direction}}发票</small><h2>{{row.number}}</h2></div><StatusTag :status="row.status"/></div><div class="invoice-paper"><div class="invoice-paper-title">电子发票 · 演示票面</div><dl class="detail-fields"><div><dt>交易对方</dt><dd>{{row.partner}}</dd></div><div><dt>当前主体</dt><dd>{{session.me?.tenants.find(t=>t.id===session.tenant)?.name}}</dd></div><div><dt>开票日期</dt><dd>{{row.date}}</dd></div><div><dt>项目名称</dt><dd>{{row.item}}</dd></div></dl><div class="invoice-amounts"><div><small>不含税金额</small><strong>¥ {{row.amount}}</strong></div><div><small>税额</small><strong>¥ {{row.tax}}</strong></div><div><small>价税合计</small><strong class="primary-text">¥ {{row.total}}</strong></div></div></div><section v-if="row.suggestion" class="suggestion-card"><div class="panel-heading"><h3>✧ 智能入账建议</h3><el-tag :type="row.suggestion.need_review?'warning':'success'">{{row.suggestion.need_review?'需人工复核':'高置信度'}}</el-tag></div><div class="suggestion-account"><div><small>推荐会计科目</small><h3>{{row.suggestion.account}}</h3></div><strong>{{(row.suggestion.confidence*100).toFixed(0)}}<small>%</small></strong></div><p>{{row.suggestion.reason}}</p><button class="evidence-toggle" @click="evidence=!evidence" :aria-expanded="evidence">{{evidence?'收起':'展开'}}置信度依据 {{evidence?'−':'＋'}}</button><div v-if="evidence" class="evidence-list"><div v-for="signal in row.suggestion.signals" :key="signal.name"><div><strong>{{signal.name}}</strong><span>权重 {{signal.weight}} · {{signal.value}}</span></div><small>{{signal.source}}</small></div><p>结果由演示服务返回，前端仅展示。</p></div></section><h3 class="section-label">处理记录</h3><el-timeline><el-timeline-item v-for="(event,i) in row.history" :key="i" color="#1565c0">{{event}}</el-timeline-item></el-timeline><el-alert title="本页为合成演示数据，查验不连接税局，凭证不写入真实账簿。" type="info" :closable="false"/></template></div><template #footer><el-button @click="emit('close')">关闭</el-button><el-button v-if="row&&['collected','verify_failed'].includes(row.status)&&session.can('invoice:write')" type="primary" :loading="busy" @click="verify">模拟查验</el-button><el-button v-if="row?.status==='verified'&&session.can('posting:write')" type="primary" :loading="busy" @click="suggest">生成入账建议</el-button><el-button v-if="row?.status==='pending_posting'&&session.can('posting:write')" type="primary" :loading="busy" @click="accept">{{row.suggestion?.need_review?'人工确认并采纳':'采纳建议'}}</el-button><el-button v-if="row?.voucher_id" type="primary" :loading="busy" @click="showVoucher">查看凭证</el-button></template></DetailDrawer><el-dialog :model-value="!!voucher" title="记账凭证 · 演示" width="min(780px,95vw)" @update:model-value="!$event&&(voucher=null)"><template v-if="voucher"><div class="voucher-meta"><span>{{voucher.number}}</span><span>会计期间 {{voucher.period}}</span></div><p>{{voucher.summary}}</p><el-table :data="voucher.lines" border><el-table-column label="会计科目" prop="account" min-width="230"/><el-table-column label="借方金额" prop="debit" align="right" width="150"/><el-table-column label="贷方金额" prop="credit" align="right" width="150"/></el-table><div class="voucher-total"><strong>合计</strong><span>借方 ¥ {{voucher.debit_total}}</span><span>贷方 ¥ {{voucher.credit_total}}</span></div><el-alert title="借贷合计由服务端返回 · 演示凭证" type="success" :closable="false"/></template></el-dialog></template>
